import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        line = line.charAt(0) + line.substring(1, line.length() - 1).replace("dot", ".") + line.charAt(line.length() - 1);
        line = line.charAt(0) + line.substring(1, line.length() - 1).replaceFirst("at", "@") + line.charAt(line.length() - 1);
        System.out.println(line);
        scanner.close();
    }
}
